result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/swr-cache/src/cache.js", "content": "/**
 * Stale-while-revalidate cache.
 *
 * Freshness windows for an entry fetched at time t:
 *   [t, t + maxAge)                                -> fresh: return cached, no fetch
 *   [t + maxAge, t + maxAge + swr)                 -> stale: return cached AND
 *                                                     fire exactly one background revalidation
 *   [t + maxAge + swr, ...)                        -> expired: fetch and await
 *
 * All fetches are single-flight per key: concurrent gets share one promise.
 */

export function createCache(fetcher, { maxAge, staleWhileRevalidate }) {
  if (typeof maxAge !== 'number' || maxAge < 0) {
    throw new Error('maxAge must be a non-negative number');
  }
  if (typeof staleWhileRevalidate !== 'number' || staleWhileRevalidate < 0) {
    throw new Error('staleWhileRevalidate must be a non-negative number');
  }

  /** @type {Map<string, {data: any, fetchedAt: number}>} */
  const entries = new Map();
  /** @type {Map<string, Promise<any>>} */
  const inFlight = new Map();

  function doFetch(key) {
    // Single-flight: reuse the in-flight promise if one exists.
    let p = inFlight.get(key);
    if (p) return p;

    p = Promise.resolve()
      .then(() => fetcher(key))
      .then((data) => {
        entries.set(key, { data, fetchedAt: now() });
        return data;
      })
      .finally(() => {
        inFlight.delete(key);
      });

    inFlight.set(key, p);
    return p;
  }

  /**
   * Returns a promise resolving to data for `key`.
   * Never rejects when only a *background* revalidation fails —
   * the caller gets the stale value; the rejection is swallowed.
   */
  async function get(key) {
    const entry = entries.get(key);

    if (!entry) {
      // No entry: fetch and await.
      return doFetch(key);
    }

    const age = now() - entry.fetchedAt;

    if (age < maxAge) {
      // Fresh.
      return entry.data;
    }

    if (age < maxAge + staleWhileRevalidate && staleWhileRevalidate > 0) {
      // Stale: serve cached value, revalidate in background.
      const bg = doFetch(key);
      // Fire-and-forget: a failed background revalidation keeps the
      // stale value and must not surface as a rejection here.
      bg.catch(() => {});
      return entry.data;
    }

    // Expired: fetch and await.
    return doFetch(key);
  }

  function now() {
    return Date.now();
  }

  return { get };
}
