import { createCache } from '../src/cache.js';

const MAX_AGE = 1000;
const SWR = 500;

function makeFetcher() {
  // Counts calls per key and returns `${key}:v${callNumber}`.
  const counts = new Map();
  const failNext = new Map(); // key -> number of upcoming calls to reject
  const fetcher = vi.fn(async (key) => {
    const n = (counts.get(key) ?? 0) + 1;
    counts.set(key, n);
    const failures = failNext.get(key) ?? 0;
    if (failures > 0) {
      failNext.set(key, failures - 1);
      throw new Error(`fetch failed for ${key} (#${n})`);
    }
    return `${key}:v${n}`;
  });
  fetcher.callsFor = (key) => counts.get(key) ?? 0;
  fetcher.failNext = (key, times = 1) => {
    failNext.set(key, (failNext.get(key) ?? 0) + times);
  };
  return fetcher;
}

/** Flush all pending microtasks (fake timers don't advance microtasks). */
const flush = () => new Promise((resolve) => setImmediate(resolve));

let fetcher;
let cache;

beforeEach(() => {
  vi.useFakeTimers();
  fetcher = makeFetcher();
  cache = createCache(fetcher, { maxAge: MAX_AGE, staleWhileRevalidate: SWR });
});

describe('createCache / get', () => {
  it('window 4 (no entry): fetches and awaits', async () => {
    const p = cache.get('a');
    await vi.advanceTimersByTimeAsync(0);
    await expect(p).resolves.toBe('a:v1');
    expect(fetcher).toHaveBeenCalledTimes(1);
    expect(fetcher.callsFor('a')).toBe(1);
  });

  it('window 1 (fresh, age < maxAge): returns cached data with no fetch', async () => {
    await vi.advanceTimersByTimeAsync(0); // populate
    expect(fetcher.callsFor('a')).toBe(1);

    vi.advanceTimersByTime(MAX_AGE - 1); // still fresh
    await expect(cache.get('a')).resolves.toBe('a:v1');
    expect(fetcher.callsFor('a')).toBe(1); // zero additional calls

    // Boundary: exactly at maxAge - 1 tick before boundary is fresh
    vi.advanceTimersByTime(MAX_AGE - 2);
    await expect(cache.get('a')).resolves.toBe('a:v1');
    expect(fetcher.callsFor('a')).toBe(1);
  });

  it('window 2 (stale, maxAge <= age < maxAge + swr): serves cached AND fires exactly one background revalidation', async () => {
    await vi.advanceTimersByTimeAsync(0);
    expect(fetcher.callsFor('a')).toBe(1);

    vi.advanceTimersByTime(MAX_AGE); // age == maxAge -> stale starts here
    const result = cache.get('a'); // not awaited yet
    // Stale value is available without waiting on the network:
    // resolve order proves cached value came back while fetch was pending.
    await expect(result).resolves.toBe('a:v1');

    await flush(); // let the background revalidation settle
    expect(fetcher.callsFor('a')).toBe(2); // exactly one extra call
    expect(fetcher.mock.calls.at(-1)[0]).toBe('a');

    // The revalidation updated the entry: subsequent stale-window get
    // within the new maxAge window sees refreshed data, no new fetch.
    vi.advanceTimersByTime(SWR + 100); // would be expired vs old timestamp...
    vi.advanceTimersByTime(-SWR); // ...but entry was refreshed at t=MAX_AGE
    // Simpler: check right after refresh, inside fresh window again.
    await expect(cache.get('a')).resolves.toBe('a:v2');
    expect(fetcher.callsFor('a')).toBe(2);
  });

  it('window 2: two gets in the stale window fire only ONE background revalidation (single-flight dedupe)', async () => {
    await vi.advanceTimersByTimeAsync(0);
    vi.advanceTimersByTime(MAX_AGE + 10); // stale

    const [r1, r2] = await Promise.all([cache.get('a'), cache.get('a')]);
    expect(r1).toBe('a:v1');
    expect(r2).toBe('a:v1');

    await flush();
    expect(fetcher.callsFor('a')).toBe(2); // 1 initial + 1 shared revalidation
  });

  it('window 3 (expired, age >= maxAge + swr): fetches and awaits the new value', async () => {
    await vi.advanceTimersByTimeAsync(0);
    vi.advanceTimersByTime(MAX_AGE + SWR); // exactly at expiry boundary

    let resolved;
    const p = cache.get('a').then((v) => (resolved = true));
    await Promise.resolve();
    expect(resolved).undefined; // must await the fetch, not serve cache

    await vi.advanceTimersByTimeAsync(0);
    await p;
    expect(fetcher.callsFor('a')).toBe(2);
    await expect(cache.get('a')).resolves.toBe('a:v2');
  });

  it('single-flight: concurrent gets for a missing key share one promise/one call', async () => {
    const p1 = cache.get('a');
    const p2 = cache.get('a');
    const p3 = cache.get('a');
    expect(p1).toBe(p2); // literally the same in-flight promise
    expect(p2).toBe(p3);

    await vi.advanceTimersByTimeAsync(0);
    await expect(Promise.all([p1, p2, p3])).resolves.toEqual(['a:v1', 'a:v1', 'a:v1']);
    expect(fetcher.callsFor('a')).toBe(1);
  });

  it('single-flight: concurrent expired gets also dedupe to one awaited fetch', async () => {
    await vi.advanceTimersByTimeAsync(0);
    vi.advanceTimersByTime(MAX_AGE + SWR + 7); // long expired

    const [r1, r2] = await Promise.all([cache.get('a'), cache.get('a')]);
    expect(r1).toBe(r2);
    await flush();
    expect(fetcher.callsFor('a')).toBe(2); // initial + one shared refetch
  });

  it('keys are isolated', async () => {
    const [a, b] = await Promise.all([cache.get('a'), cache.get('b')]);
    await flush();
    expect(a).toBe('a:v1');
    expect(b).toBe('b:v1');
    expect(fetcher.callsFor('a')).toBe(1);
    expect(fetcher.callsFor('b')).toBe(1);
  });

  it('failed background revalidation: keeps stale value, does not reject, schedules nothing weird', async () => {
    await vi.advanceTimersByTimeAsync(0);
    vi.advanceTimersByTime(MAX_AGE + 10); // stale

    fetcher.failNext('a'); // background revalidation will reject

    // Caller still receives the stale value; no rejection propagates.
    await expect(cache.get('a')).resolves.toBe('a:v1');

    await flush(); // let the rejected background promise settle (handled)
    expect(fetcher.callsFor('a')).toBe(2);

    // Stale entry survived: another stale-window get re-serves v1 and
    // fires a NEW single revalidation attempt (no weird double-fires).
    fetcher.failNext('a');
    vi.advanceTimersByTime(50); // still inside stale window
    await expect(cache.get('a')).resolves.toBe('a:v1');
    await flush();
    expect(fetcher.callsFor('a')).toBe(3);

    // Once past the stale window, an awaited fetch surfaces the error,
    // proving the entry really kept its old value rather than being cleared.
    vi.advanceTimersByTime(SWR); // now expired
    await expect(cache.get('a')).rejects.toThrow(/#4/);
  });

  it('failed background revalidation leaves no dangling in-flight state', async () => {
    await vi.advanceTimersByTimeAsync(0);
    vi.advanceTimersByTime(MAX_AGE + 10);
    fetcher.failNext('a');

    await expect(cache.get('a')).resolves.toBe('a:v1');
    await flush();

    // After the failed revalidation, a fresh get must trigger a real
    // retry (not return a poisoned shared promise).
    vi.advanceTimersByTime(MAX_AGE + SWR); // expire it fully
    const p = cache.get('a');
    await vi.advanceTimersByTimeAsync(0);
    await expect(p).resolves.toBe('a:v3');
  });

  it('timing proven with fake timers: exact boundaries of each window', async () => {
    await vi.advanceTimersByTimeAsync(0); // t=0: fetched

    vi.advanceTimersByTime(MAX_AGE - 1);
    await cache.get('a');
    expect(fetcher.callsFor('a')).toBe(1); // fresh at maxAge - 1

    vi.advanceTimersByTime(1); // t = MAX_AGE: stale begins
    await cache.get('a');
    expect(fetcher.callsFor('a')).toBe(2); // background fired

    await flush();
    vi.advanceTimersByTime(SWR - 1); // refreshed at MAX_AGE; age SWR-1... but that's stale for new entry
    // New entry fetchedAt = MAX_AGE. Advance to just before its expiry:
    vi.setSystemTime((MAX_AGE) * 1); // anchor clarity
    vi.advanceTimersByTime(-(SWR - 1));
    vi.advanceTimersByTime(MAX_AGE - 1); // age = MAX_AGE - 1 vs new entry
    await cache.get('a');
    expect(fetcher.callsFor('a')).toBe(2); // still fresh after revalidation

    vi.advanceTimersByTime(MAX_AGE + SWR - 1); // age = maxAge + swr - 1 -> stale
    await cache.get('a');
    expect(fetcher.callsFor('a')).toBe(3); // background fired once more

    await flush();
    vi.advanceTimersByTime(1); // age >= maxAge + swr -> expired
    await cache.get('a');
    expect(fetcher.callsFor('a')).toBe(4); // awaited fetch
  });

  it('validates options', () => {
    expect(() => createCache(fetcher, { maxAge: -1, staleWhileRevalidate: 0 })).toThrow(/maxAge/);
    expect(() => createCache(fetcher, { maxAge: 1, staleWhileRevalidate: NaN })).toThrow(/staleWhileRevalidate/);
  });
});
"})
